#!/usr/bin/env python3
"""Archive pinned third-party source as data; never vendor it into the build.

Collection is explicit. Verification is offline in check_third_party.py.
Go module ZIPs retain their official module-prefix paths and go.sum h1 digest.
Full upstream tarballs supplement (not replace) module snapshots when obtainable.
"""
import argparse
import base64
from concurrent.futures import ThreadPoolExecutor
import hashlib
import html
from html.parser import HTMLParser
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import tarfile
import threading
import zipfile

ROOT = Path(__file__).resolve().parents[1]
GO = "/opt/homebrew/bin/go" if Path("/opt/homebrew/bin/go").exists() else "go"


def records(text):
    decoder = json.JSONDecoder()
    while text.strip():
        text = text.lstrip()
        row, end = decoder.raw_decode(text)
        yield row
        text = text[end:]


def sha(path):
    h = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def module_h1(path):
    # Go's documented dirhash.Hash1 format, including module@version prefix.
    h = hashlib.sha256()
    with zipfile.ZipFile(path) as archive:
        for name in sorted(x.filename for x in archive.infolist() if not x.is_dir()):
            if "\n" in name or ".." in Path(name).parts or Path(name).is_absolute():
                raise ValueError("unsafe module archive path")
            h.update((hashlib.sha256(archive.read(name)).hexdigest() + "  " + name + "\n").encode())
    return "h1:" + base64.b64encode(h.digest()).decode()


def archive_info(path):
    from source_archives import audit_archive
    return {"path":path.relative_to(ROOT).as_posix(), **audit_archive(path)}


def public_gh(endpoint):
    return json.loads(subprocess.check_output(["gh", "api", endpoint], text=True, timeout=35))


SOURCE_LOCK = threading.Lock()

def github_source(repo, ref, target):
    with SOURCE_LOCK:
        return github_source_serial(repo, ref, target)

def github_source_serial(repo, ref, target):
    commit = public_gh("repos/" + repo + "/commits/" + ref)["sha"]
    file = target / (repo.replace("/", "--") + "--" + commit + ".tar.gz")
    if not file.exists():
        partial = file.with_suffix(file.suffix + ".partial")
        try:
            with partial.open("wb") as output:
                subprocess.run(["gh", "api", "repos/" + repo + "/tarball/" + commit], stdout=output, check=True, timeout=90)
            archive_info(partial)
            partial.rename(file)
        finally:
            partial.unlink(missing_ok=True)
    return {"kind": "full-upstream-source-archive", "repository": "https://github.com/" + repo,
            "commit": commit, "ref": ref, "url": "https://api.github.com/repos/" + repo + "/tarball/" + commit,
            **archive_info(file)}


def repo_ref(module, version):
    pseudo = re.search(r"-\d{14}-([0-9a-f]{12})$", version)
    if module.startswith("github.com/"):
        parts = module.split("/"); repo = "/".join(parts[1:3]); rest = parts[3:]
        if rest and re.fullmatch(r"v\d+", rest[-1]): rest = rest[:-1]
    elif module.startswith("golang.org/x/"):
        parts = module.split("/"); repo = "golang/" + parts[2]; rest = parts[3:]
    else:
        maps = {"gopkg.in/yaml.v3": ("go-yaml/yaml", []),
                "gopkg.in/check.v1": ("go-check/check", []),
                "gopkg.in/errgo.v2": ("go-errgo/errgo", []),
                "go.yaml.in/yaml/v3": ("yaml/go-yaml", []),
                "go.yaml.in/yaml/v4": ("yaml/go-yaml", [])}
        if module not in maps: return None
        repo, rest = maps[module]
    return repo, pseudo.group(1) if pseudo else "/".join(rest + [version])


def write_manifest(manifest):
    # One generated component per line; the reader-facing inventory is separate.
    components = manifest.pop("components")
    prefix = json.dumps(manifest, ensure_ascii=False, indent=2).rstrip()[:-1]
    text = prefix + ',\n  "components": [\n' + ',\n'.join('    ' + json.dumps(row, ensure_ascii=False, separators=(',', ':')) for row in components) + '\n  ]\n}\n'
    (ROOT / "third_party/sources.json").write_text(text)
    manifest["components"] = components
    write_inventory(manifest)


def render_inventory(manifest):
    components = manifest["components"]
    archives = {a["path"]:a for c in components for a in c["archives"]}
    modules = [c for c in components if c["scope"] in ("production-package-closure","selected-test-or-generation-graph")]
    verified = sum(any("go_sum_h1" in a for a in c["archives"]) for c in modules)
    text = ["# Third-party source inventory", "", "Generated by `scripts/collect_third_party.py`; do not hand-edit this index or `sources.json`.", "", f"{len(components)} components · {len(archives)} unique source archives · {sum(a['bytes'] for a in archives.values()):,} compressed bytes · {sum(a['source_bytes'] for a in archives.values()):,} regular-file source bytes.", "", f"The Go-pruned selected engine module graph contains {len(modules)} modules; {sum(c['scope']=='production-package-closure' for c in modules)} occur in the union of six-platform production imports. {verified} module ZIPs are additionally bound to `engine/go.sum` h1 values. All selected modules have official full upstream source archives. Unavailable module ZIPs are not represented as missing source, nor as h1-verified equivalents.", "", "## Boundaries", "", "Archives are inert source data, not vendoring. No downloaded source, build hook or test is run during collection or verification. Builds still use the unchanged engine module files. The component count is a top-level inventory, not a claim to enumerate every embedded upstream vendor/test asset as a separate product; those original trees and notices remain in their complete archives. Source ZIPs are complete module snapshots; upstream archives are full provider snapshots at the recorded tag/commit, without Git history. The actual JSONSchema test-suite submodule is included at its parent's pinned Gitlink commit, not at moving main.", "", "SQLite includes both modernc's generated implementation and original SQLite 3.51.2 source. The Go archive is the version declared in engine/go.mod, not a claim about the compiler used by every binary or this review. Mage/nfpm/actionlint are complete upstream tool-source snapshots at versions pinned by CI; their separate tool-development dependency graphs, hosted Actions, browser binaries, OS SDKs, proprietary agents and model services are not this engine dependency closure or an archived CI machine.", "", "Sonar is historical provenance, not a runtime dependency. GSAP has its own license, not MIT. The independent macOS client's fonts and SwiftTerm are not shipped here. Original root-level legal files are additionally indexed byte-for-byte for reading; this does not override licenses in embedded subtrees. Original LICENSE/NOTICE/header files remain in the archives; supplemental legal documents are under [licenses/](licenses/). See [notices](../THIRD_PARTY_NOTICES.md) and the [source guide](../docs/third-party.md) / [中文说明](../docs/third-party.zh.md).", "", "## Extraction warning", "", "Verify before inspection with `python3 scripts/check_third_party.py`. Extract only into a new directory outside the checkout with path/link safety filtering. Do not execute downloaded scripts merely to inspect source. In particular, the original nfpm test fixture `files/testdata/tree/symlinks/link1` points to `/etc/foo`; this intentionally unsafe fixture is preserved as archive data, explicitly inventoried, and never extracted by these scripts. Do not blindly unpack all tool fixtures.", "", "## Fixed versions and real source", "", "| Component | Version | Scope | Archives | Original legal files |", "|---|---|---|---|---|"]
    for c in components:
        links = [f"[{('module' if 'go_sum_h1' in a else 'upstream')}]({a['path'].removeprefix('third_party/')})" for a in c["archives"]]
        legal = [f"[{Path(n).name}]({n.removeprefix('third_party/')})" for n in c.get("license_documents",[])]
        text.append(f"| `{c['id']}` | `{c['version']}` | {c['scope']} | {' · '.join(links)} | {' · '.join(legal)} |")
    text += ["", "## Verification and intentional updates", "", "The JSON inventory retains original source URLs, commit/tag, archive SHA-256, sizes, file counts, license paths, submodule relationship and exceptional symlinks. Input hashes bind it to the module files, site lockfile, copied GSAP asset and tool-pinning workflows.", "", "Run `python3 scripts/check_third_party.py` for offline integrity, selected-graph and six-target production-closure checks; Go and the existing module metadata cache are required. It does not run archived code. `python3 -m unittest discover -s scripts -p check_third_party_test.py` exercises corruption, missing source, h1 binding, unsafe paths, LFS placeholders, submodules and legal-document checks using synthetic temporary data.", "", "After an intentional dependency/tool-version change, review and update the collector's explicit source pins, then run `python3 scripts/collect_third_party.py --collect` (Go, gh and curl required). It reads official public sources and verified cached module ZIPs, does not install anything, and fails verification if a source gap remains. Review all provenance/license/hash changes; do not update a checksum just to silence failure.", "", "Network record: the public Go proxy timed out, so no alternate proxy was used; canonical modernc GitLab source archives were available. SQLite's official download host hit an SSL timeout; its official GitHub mirror at the fixed version commit supplied the full original source. The official GSAP license-page snapshot was retrieved on 2026-11-15 Asia/Shanghai and is a current page snapshot, not a historically versioned license.", ""]
    return "\n".join(text)


def write_inventory(manifest):
    (ROOT / "third_party/README.md").write_text(render_inventory(manifest))


def gsap_license_text(raw):
    class License(HTMLParser):
        def __init__(self):
            super().__init__(); self.depth = 0; self.parts = []
        def handle_starttag(self, tag, attrs):
            if not self.depth and dict(attrs).get("id") == "license": self.depth = 1
            elif self.depth and tag not in {"br","hr","img","input","meta","link","source","wbr"}: self.depth += 1
            if self.depth and tag in {"h2","h3","p","li","br"}: self.parts.append("\n")
        def handle_endtag(self, tag):
            if tag in {"br","hr","img","input","meta","link","source","wbr"}: return
            if self.depth:
                if tag in {"h2","h3","p","li"}: self.parts.append("\n")
                self.depth -= 1
        def handle_data(self, data):
            if self.depth: self.parts.append(data)
    parser = License(); parser.feed(raw)
    text = "\n".join(re.sub(r"[ \t]+", " ", line).strip() for line in "".join(parser.parts).splitlines() if line.strip())
    if 'Standard "No Charge" GSAP License' not in text or "DEFINITIONS" not in text:
        raise ValueError("Official GSAP legal-body extraction failed")
    return "Source: https://gsap.com/standard-license\nRetrieved: 2026-11-15 Asia/Shanghai; plain text extracted from preserved HTML, not a historical versioned license.\n\n" + text + "\n"


def collect_source_trees(manifest):
    output = ROOT / "third_party/source-trees.json"
    previous = json.loads(output.read_text()) if output.exists() else {}
    archives = {a["path"]:a for c in manifest["components"] for a in c["archives"] if a.get("repository", "").startswith("https://github.com/")}
    def tree(item):
        name, archive = item
        if name in previous: return name, previous[name]
        repo = archive["repository"].removeprefix("https://github.com/")
        endpoint = "repos/" + repo + "/git/trees/" + archive["commit"] + "?recursive=1"
        row = public_gh(endpoint)
        if row.get("truncated"): raise ValueError("Incomplete upstream Git tree: " + repo)
        with tarfile.open(ROOT/name) as source:
            included = {m.name.split("/",1)[1] for m in source if (m.isfile() or m.issym() or m.islnk()) and "/" in m.name}
        tracked = {m["path"] for m in row["tree"] if m["type"] == "blob"}
        return name, {"source":"https://api.github.com/" + endpoint,"commit":archive["commit"],"tree_sha":row["sha"],"blob_count":len(tracked),"omitted_tracked_files":sorted(tracked-included),"unexpected_archive_files":sorted(included-tracked),"gitlinks":[{"path":m["path"],"commit":m["sha"]} for m in row["tree"] if m["mode"] == "160000"]}
    with ThreadPoolExecutor(max_workers=4) as pool:
        result = dict(pool.map(tree, archives.items()))
    output.write_text(json.dumps(result,sort_keys=True,indent=2) + "\n")
    return {"path":output.relative_to(ROOT).as_posix(),"sha256":sha(output),"bytes":output.stat().st_size}


def collect_root_license_documents(manifest):
    # Copy original root-level legal files byte-for-byte for convenient reading.
    # This is an index, not relicensing of embedded vendor/test subtrees.
    documents = [d for d in manifest["license_documents"] if "/components/" not in d["path"]]
    for component in manifest["components"]:
        component["license_documents"] = []
        source = next(a for a in component["archives"] if a["kind"] == "full-upstream-source-archive")
        destination = ROOT / "third_party/licenses/components" / (component["id"].replace("/","--")+"@"+component["version"])
        with tarfile.open(ROOT/source["path"]) as archive:
            for member in archive:
                if not member.isfile() or len(Path(member.name).parts) != 2: continue
                if not any(word in Path(member.name).name.lower() for word in ("license","licence","copying","notice","copyright","patents")): continue
                destination.mkdir(parents=True,exist_ok=True)
                file = destination / Path(member.name).name
                file.write_bytes(archive.extractfile(member).read())
                name = file.relative_to(ROOT).as_posix()
                component["license_documents"].append(name)
                documents.append({"path":name,"sha256":sha(file),"bytes":file.stat().st_size,"source":"Original bytes from "+source["path"]+":"+member.name})
        if not component["license_documents"]:
            if component["id"] != "GSAP": raise ValueError("No root legal document; review provenance: "+component["id"])
            component["license_documents"] = ["third_party/licenses/gsap-standard-license.txt"]
    manifest["license_documents"] = documents


def collect():
    env = dict(os.environ, GOPROXY="off", GOTOOLCHAIN="local", GOWORK="off")
    graph = subprocess.check_output([GO,"mod","graph"],cwd=ROOT/"engine",env=env,text=True)
    graph_file = ROOT/"third_party/module-graph.txt"; graph_file.write_text("\n".join(sorted(graph.splitlines()))+"\n")
    rows = [r for r in records(subprocess.check_output([GO, "list", "-mod=readonly", "-m", "-e", "-json", "all"], cwd=ROOT/"engine",env=env,text=True)) if not r.get("Main")]
    cache = Path(subprocess.check_output([GO, "env", "GOMODCACHE"],text=True).strip()) / "cache/download"
    sums = {(m,v):h for m,v,h in (line.split() for line in (ROOT/"engine/go.sum").read_text().splitlines())}
    declared = dict(re.findall(r"^\s*([^\s()]+) (v\S+)", (ROOT/"engine/go.mod").read_text(), re.M))
    runtime = set()
    for goos, goarch in [("darwin","arm64"),("darwin","amd64"),("linux","amd64"),("linux","arm64"),("windows","amd64"),("windows","arm64")]:
        text = subprocess.check_output([GO,"list","-mod=readonly","-deps","-json","./..."],cwd=ROOT/"engine",env=dict(env,GOOS=goos,GOARCH=goarch,CGO_ENABLED="0"),text=True)
        runtime |= {r["Module"]["Path"] for r in records(text) if r.get("Module") and not r["Module"].get("Main")}
    target=ROOT/"third_party/sources"; (target/"modules").mkdir(parents=True,exist_ok=True); (target/"upstream").mkdir(exist_ok=True)
    def component(row):
        module,version=row["Path"],row["Version"]
        entry={"id":module,"version":version,"scope":"production-package-closure" if module in runtime else "selected-test-or-generation-graph", "declared":module in declared,"modified":False,"archives":[],"gaps":[]}
        escaped="".join("!"+c.lower() if c.isupper() else c for c in module)
        cached=cache/escaped/"@v"/(version+".zip")
        if cached.exists():
            expected=sums.get((module,version))
            actual=module_h1(cached)
            if expected is None or actual!=expected: raise ValueError("module h1 mismatch or unrecorded checksum: "+module)
            output=target/"modules"/(module.replace("/","--")+"@"+version+".zip")
            shutil.copyfile(cached,output)
            entry["archives"].append({"kind":"complete-go-module-snapshot-not-whole-upstream-repository","url":"https://proxy.golang.org/"+escaped+"/@v/"+version+".zip","go_sum_h1":actual,**archive_info(output)})
        else: entry["module_zip_status"] = "Not cached; official full upstream source is included instead. No module-ZIP h1 equivalence is asserted."
        mapping=repo_ref(module,version)
        if mapping:
            try: entry["archives"].append(github_source(*mapping,target/"upstream"))
            except (subprocess.SubprocessError,KeyError,ValueError,OSError) as error:
                entry["gaps"].append("Official upstream source unavailable: "+type(error).__name__)
        elif module.startswith("modernc.org/"):
            # The canonical cznic repositories are on GitLab, not an unofficial GitHub mirror.
            repo=module.split('/')[1];url="https://gitlab.com/cznic/"+repo+"/-/archive/"+version+"/"+repo+"-"+version+".tar.gz"
            output=target/"upstream"/("cznic--"+repo+"--"+version+".tar.gz")
            try:
                if not output.exists(): subprocess.run(["curl","--fail","--location","--connect-timeout","8","--max-time","30","--silent","--show-error",url,"-o",str(output)],check=True,timeout=35)
                entry["archives"].append({"kind":"full-upstream-source-archive","repository":"https://gitlab.com/cznic/"+repo,"ref":version,"url":url,**archive_info(output)})
            except (subprocess.SubprocessError,ValueError,OSError,tarfile.TarError):
                output.unlink(missing_ok=True);entry["gaps"].append("Canonical GitLab source archive unavailable; any included module ZIP is a complete module snapshot, not a full upstream repository.")
        print("SOURCE",module,version,len(entry['archives']),"archives",len(entry['gaps']),"gaps",flush=True)
        return entry
    with ThreadPoolExecutor(max_workers=4) as pool: components=list(pool.map(component,rows))
    for ident,repo,ref,scope in [("GSAP","greensock/GSAP","5e6c35ff8eedea12d4f229129def635277d8b0f2","distributed-site-asset"),("Playwright","microsoft/playwright","v1.63.0","site-development-tools"),("Sonar","raskrebs/sonar","be48afbee89fd2381d0e2c8b0aa9ec1d81194546","historical-provenance-not-a-runtime-dependency"),("SQLite","sqlite/sqlite","version-3.51.2","embedded-sqlite-original-source"),("JSON-Schema-Test-Suite","json-schema-org/JSON-Schema-Test-Suite","83e866b46c9f9e7082fd51e83a61c5f2145a1ab7","upstream-test-submodule-source"),("Go","golang/go","go1.25.0","declared-go-toolchain-source"),("Mage","magefile/mage","v1.17.2","external-build-tool-source"),("nfpm","goreleaser/nfpm","v2.46.0","external-packaging-tool-source"),("actionlint","rhysd/actionlint","v1.7.7","external-ci-lint-tool-source")]:
        entry={"id":ident,"version":{"GSAP":"3.15.1","Playwright":"1.63.0","SQLite":"3.51.2"}.get(ident,ref),"scope":scope,"modified":False,"archives":[],"gaps":[]}
        try: entry['archives'].append(github_source(repo,ref,target/'upstream'))
        except (subprocess.SubprocessError,KeyError,ValueError,OSError) as error: entry['gaps'].append(type(error).__name__)
        components.append(entry)
    parent = next(c for c in components if c["id"] == "github.com/santhosh-tekuri/jsonschema/v6")
    parent["submodule_dependencies"] = [{"path":"testdata/JSON-Schema-Test-Suite","repository":"https://github.com/json-schema-org/JSON-Schema-Test-Suite","commit":"83e866b46c9f9e7082fd51e83a61c5f2145a1ab7","component":"JSON-Schema-Test-Suite","evidence":"GitHub recursive tree at parent b0fc661f4939578bc429f408c18202573dbafcc4, mode 160000"}]
    manifest={"format_version":1,"base_revision":subprocess.check_output(["git","rev-parse","HEAD"],cwd=ROOT,text=True).strip(),"inputs":{p:sha(ROOT/p) for p in [".gitattributes","engine/go.mod","engine/go.sum","site/package-lock.json","site/assets/gsap.min.js",".github/workflows/engine.yml",".github/workflows/release.yml",".github/workflows/ci-config.yml",".github/workflows/agent-eval.yml"]},"platforms":["darwin/arm64","darwin/amd64","linux/amd64","linux/arm64","windows/amd64","windows/arm64"],"resolution":"Source archives only. No replace directive, vendor mode, dependency update, downloaded scripts or source execution.","components":components}
    licenses = ROOT / "third_party/licenses"
    licenses.mkdir(exist_ok=True)
    sonar = next(x for x in components if x["id"] == "Sonar")
    with tarfile.open(ROOT / sonar["archives"][0]["path"]) as archive:
        name = next(n for n in archive.getnames() if n.endswith("/LICENSE"))
        (licenses / "Sonar-MIT.txt").write_bytes(archive.extractfile(name).read())
    gsap_license = licenses / "gsap-standard-license.html"
    if not gsap_license.exists():
        subprocess.run(["curl", "--fail", "--location", "--connect-timeout", "8", "--max-time", "30", "--silent", "--show-error", "https://gsap.com/standard-license", "-o", str(gsap_license)], check=True, timeout=35)
    if 'Standard "No Charge" GSAP License' not in html.unescape(gsap_license.read_text()):
        raise ValueError("GSAP license response is not the actual license")
    (licenses / "gsap-standard-license.txt").write_text(gsap_license_text(gsap_license.read_text()))
    manifest["license_documents"] = [{"path":p.relative_to(ROOT).as_posix(),"sha256":sha(p),"bytes":p.stat().st_size,"source":source} for p,source in [(licenses/"Sonar-MIT.txt","Original LICENSE in pinned Sonar source archive"),(licenses/"gsap-standard-license.txt","Legal-body text extracted from preserved official GSAP HTML snapshot"),(gsap_license,"https://gsap.com/standard-license (retrieved 2026-11-15 Asia/Shanghai; current official license page, not a versioned historical license)")]]
    collect_root_license_documents(manifest)
    manifest["module_graph"] = {"path":"third_party/module-graph.txt","sha256":sha(graph_file),"meaning":"Strict offline Go-pruned selected module graph, not recursively every external tool ecosystem"}
    manifest["source_trees"] = collect_source_trees(manifest)
    write_manifest(manifest)
    print('SOURCE MANIFEST',len(components),'components; gaps:',sum(bool(x['gaps']) for x in components),flush=True)

if __name__=="__main__":
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--collect',action='store_true',required=True);p.parse_args();collect()
